+    draft(&mut h).flutes = Some(4);
+    draft(&mut h).helix_deg = "30".into();
+    h.run_steps(2);
+    let texts = painted(&h);
+    for want in [format!("{} · mm", side_view::TO_SCALE), side_view::NOSE.to_owned(), "BT30 ER20".to_owned()] {
+        assert!(texts.contains(&want), "the side drawing paints {want:?}: {texts:?}");
